let currentWorkshopEpoch=0;
export async function request(path:string,method='GET',body?:unknown):Promise<any>{
 if(method!=='GET'&&/^\/workshop\/(?:host\/)?[A-Z0-9]{6}\//.test(path))body={...(body as any),epoch:currentWorkshopEpoch};
 const r=await fetch(apiOrigin+'/api'+path,{method,headers:{'Content-Type':'application/json','x-signal-request':'1',...(/^\/(auth\/admin|admin\/|workshop\/(?:host|access))/.test(path)?authHeaders(true):frontendRoute().kind==='demo'?{Authorization:'Bearer '+(sessionStorage.getItem('signal-demo-token')||'')}:authHeaders())},body:body===undefined?undefined:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Object.assign(new Error(d.error||'Unable to reach the seminar service.'),{status:r.status});if(d.session?.resetEpoch!==undefined||d.resetEpoch!==undefined)currentWorkshopEpoch=Math.max(currentWorkshopEpoch,d.session?.resetEpoch??d.resetEpoch);if(path==='/auth/guest')saveApiSession(d.token);if(path==='/auth/admin/login')sessionStorage.setItem('signal-admin-token',d.token);return d;
}
