const sum=(arr:any[],key:string)=>arr.reduce((n,v)=>n+Number(v[key]||0),0);
export function SeminarQR(){let url=new URLSearchParams(location.search).get('join')||new URL(browserPath('/audience'),location.href).href;try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw 0;}catch{url=new URL(browserPath('/audience'),location.href).href;}return <div className="w-qr-only"><QRCodeSVG value={url} size={240} marginSize={3}/><a href={url} target="_blank" rel="noreferrer">Join the workshop</a></div>;}
