 async function refresh(c=code){const d=await request(admin?'/workshop/host/'+c:'/workshop/'+c+'/state');if((d.session?.resetEpoch??d.resetEpoch??0)<currentWorkshopEpoch)return;admin?setHost(d):setState(d);setOffline(false);history.replaceState(null,'',browserPath(demo?'/admin/demo':admin?'/admin':'/audience'));}
 async function run(fn:()=>Promise<any>){setBusy(true);setError('');try{await fn();return true;}catch(e){setError(e instanceof Error?e.message:'Request failed');return false;}finally{setBusy(false);}}
 async function loadAdmin(){await request('/auth/admin/me');const d=await request('/workshop/access');setAddresses(d.addresses);if(['localhost','127.0.0.1'].includes(location.hostname))setBase(d.addresses.find((a:string)=>a.includes('192.168.'))||d.addresses[0]||location.origin);await refresh();setAdminReady(true);}
