 useEffect(()=>{if(!admin||adminReady||!sessionStorage.getItem('signal-admin-token'))return;const timer=setInterval(()=>void loadAdmin().catch(e=>{if([401,403].includes(e?.status)){sessionStorage.removeItem('signal-admin-token');setAdminReady(false);clearInterval(timer);}}),3000);return()=>clearInterval(timer);},[admin,adminReady]);
