function Setup({p,busy,action,initialStep=0,initialOrg="",initialGoals=[]}:any){
 const {t,copy}=useWords(),[step,setStep]=useState(initialStep),[orgId,setOrgId]=useState(initialOrg),[goals,setGoals]=useState<string[]>(initialGoals),[name,setName]=useState(organizations.find(o=>o.id===initialOrg)?.name||'');
 const org=organizations.find(o=>o.id===orgId);
 return <div className="w-setup"><div className="w-steps"><span className={step===0?'active':''}>01 {t('Organization','Organisasi')}</span><span className={step===1?'active':''}>02 {t('Objectives','Tujuan')}</span></div><h1>{step===0?t('Which organization will you lead?','Organisasi mana yang akan Anda pimpin?'):t('What will you be accountable for?','Tujuan apa yang menjadi tanggung jawab Anda?')}</h1><p>{step===0?t('Each organization has a different growth strategy and market exposure. Choose one you would like to lead.','Setiap organisasi memiliki strategi pertumbuhan dan eksposur pasar berbeda. Pilih yang ingin Anda pimpin.'):t('Select at least one objective. Its risks, controls, owners and mitigation plans are ready for your review.','Pilih minimal satu tujuan. Risiko, pengendalian, pemilik, dan rencana mitigasinya telah tersedia.')}</p>
 {step===0?<><div className="w-org-grid">{organizations.map((o,i)=>{const Icon=[Truck,ShoppingBasket,Monitor][i];return <button key={o.id} className={'w-org '+(orgId===o.id?'selected':'')} onClick={()=>{setOrgId(o.id);setName(o.name);setGoals([]);}}><Icon size={32}/><small>{copy(o.industry)}</small><h2>{o.name}</h2><p>{copy(o.profile)}</p><span>{o.objectives.length} {t('objectives','tujuan')} · {o.risks.length} {t('risks','risiko')}</span>{orgId===o.id&&<Check size={20}/>}</button>;})}</div><button className="w-quiet" onClick={()=>{const o=organizations[Math.floor(Math.random()*3)];setOrgId(o.id);setName(o.name);setGoals([]);}}><Shuffle size={16}/>{t('Choose for me','Pilihkan untuk saya')}</button></>:<><div className="w-panel"><h2>{org?.name}</h2><label>{t('Company name','Nama perusahaan')}<input value={name} maxLength={100} onChange={e=>setName(e.target.value)}/></label><button className="w-quiet" onClick={()=>setName(org!.name+' '+['Utama','Mandiri','Sejahtera'][Math.floor(Math.random()*3)])}><Shuffle size={15}/>{t('Fill a name','Isi nama')}</button></div><div className="w-objectives">{org?.objectives.map(o=><label key={o.id} className={goals.includes(o.id)?'selected':''}><input type="checkbox" checked={goals.includes(o.id)} onChange={e=>setGoals(e.target.checked?[...goals,o.id]:goals.filter(v=>v!==o.id))}/><span><b>{copy(o.title)}</b><small>{copy(o.target)}</small></span><b>2 {t('risks','risiko')}</b></label>)}</div><button className="w-quiet" onClick={()=>setGoals([org!.objectives[Math.floor(Math.random()*2)].id])}><Shuffle size={15}/>{t('Choose an objective for me','Pilihkan tujuan')}</button><p className="w-note">{t('Profiles and internal evidence are teaching cases. External news links refer to real published reports.','Profil dan bukti internal merupakan kasus pembelajaran. Tautan berita eksternal merujuk pada berita yang benar-benar diterbitkan.')}</p></>}
 <div className="w-actions">{step===1&&<button onClick={()=>setStep(0)}>{t('Back','Kembali')}</button>}<button className="w-primary" disabled={busy||!orgId||step===1&&!goals.length} onClick={()=>step===0?setStep(1):action('/setup','PUT',{organizationId:orgId,objectiveIds:goals,company:name,sourceIds:p.sourceIds})}>{step===0?t('Continue','Lanjutkan'):t('Open workspace','Buka ruang kerja')}<ArrowRight size={17}/></button></div></div>;
}
function Dashboard({p,onReview}:{p:Participant;onReview:()=>void}){
 const {t,copy}=useWords(),org=organizations.find(o=>o.id===p.organizationId)!,pending=p.signals.filter(s=>!s.decision).length,above=p.risks.filter(r=>{const v=projection(r,p.plans);return v.likelihood*v.impact>12;}).length;
 function download(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)],{type:'application/json'}));a.download='signal-decisions.json';a.click();URL.revokeObjectURL(a.href);}
 return <><div className="w-heading"><h1>{t('Your decisions, in context','Keputusan Anda dalam konteks')}</h1><button onClick={download}>{t('Download decision record','Unduh catatan keputusan')}</button></div><div className="w-stats">{[[p.risks.length,t('Registered risks','Risiko terdaftar')],[pending,t('Signals to review','Sinyal perlu ditinjau')],[above,t('Projected above tolerance','Proyeksi melebihi toleransi')],[p.plans.filter(v=>v.status==='Open').length,t('Open actions','Tindakan terbuka')]].map(([n,label])=><div key={label}><strong>{n}</strong><span>{label}</span></div>)}</div>
 <p className="w-note">{p.plans.filter(v=>v.status==='Open'&&v.dueDate>=featured.exerciseDate&&v.dueDate<=due(featured.exerciseDate,7)).length} {t('actions due within seven exercise days','tindakan jatuh tempo dalam tujuh hari latihan')} {'\u00b7'} {p.plans.filter(v=>v.status==='Open'&&v.dueDate<featured.exerciseDate).length} {t('overdue','lewat tenggat')}</p><div className="w-dashboard-grid"><section className="w-panel"><h2>{t('Objectives under your care','Tujuan yang Anda kelola')}</h2>{org.objectives.filter(o=>p.objectiveIds.includes(o.id)).map(o=><div className="w-goal" key={o.id}><b>{copy(o.title)}</b><span>{copy(o.target)}</span><small>{t('Measured actual: not supplied. Risk scores do not predict KPI percentages.','Realisasi terukur: belum tersedia. Skor risiko tidak memprediksi persentase capaian KPI.')}</small><b className={p.risks.some(r=>r.objectiveId===o.id&&projection(r,p.plans).likelihood*projection(r,p.plans).impact>12)?'w-danger':'w-green'}>{p.risks.some(r=>r.objectiveId===o.id&&projection(r,p.plans).likelihood*projection(r,p.plans).impact>12)?t('Projected residual needs further treatment','Residual proyeksi memerlukan tindak lanjut'):t('Projected within tolerance; monitor plan delivery','Proyeksi dalam toleransi; pantau pelaksanaan mitigasi')}</b></div>)}</section><section className="w-panel"><h2>{t('Projected residual risk map','Peta risiko residual proyeksi')}</h2><RiskMap risks={p.risks.map(r=>({...r,...projection(r,p.plans)}))}/><small>{t('Assumes planned mitigation achieves its stated effect. Assessed scores remain in the decision history. Tolerance: 12.','Mengasumsikan mitigasi terlaksana sesuai proyeksi. Skor penilaian tersimpan dalam riwayat keputusan. Toleransi: 12.')}</small></section></div>
 <section className="w-panel"><div className="w-heading"><h2>{t('Evidence reaching decisions','Bukti yang menjadi dasar keputusan')}</h2><button className="w-primary" onClick={onReview}>{t('Review risks','Tinjau risiko')}<ArrowRight size={16}/></button></div><div className="w-flow-count">{[[p.signals.length,t('Received','Diterima')],[p.signals.filter(s=>s.decision==='Capture').length,t('Captured','Ditangkap')],[p.reviews.length,t('Assessments reviewed','Penilaian ditinjau')],[p.plans.filter(v=>v.signalIds.length).length,t('Responses agreed','Respons disepakati')]].map(([n,l])=><div key={l}><strong>{n}</strong><span>{l}</span></div>)}</div><p className="w-note">{t('A justified neglect or unchanged assessment is a valid decision. Approved plans show expected protection; current risk stays unchanged until reassessed.','Pengabaian beralasan atau penilaian tetap merupakan keputusan yang sah. Rencana disetujui menunjukkan perlindungan yang diharapkan; risiko saat ini tetap sampai dinilai ulang.')}</p></section>
 <section className="w-panel"><h2>{t('Decision history','Riwayat keputusan')}</h2>{p.reviews.length?p.reviews.slice().reverse().map(v=><div className="w-history" key={v.id}><b>{copy(p.risks.find(r=>r.id===v.riskId)?.title)}</b><span>{v.before.likelihood*v.before.impact} → {v.after.likelihood*v.after.impact} · {v.choice==='Keep'?t('Kept','Dipertahankan'):t('Updated','Diperbarui')}</span><p>{v.notes}</p><small>{new Date(v.at).toLocaleString()} · {v.signalIds.length} {t('sources','sumber')}</small></div>):<p>{t('Your first evidence-linked assessment will appear here.','Penilaian pertama yang terkait bukti akan muncul di sini.')}</p>}</section></>;
}
function RiskMap({risks,value,onChange,suggestion,previous}:{risks?:Risk[];value?:{likelihood:number;impact:number};onChange?:(v:{likelihood:number;impact:number})=>void;suggestion?:{likelihood:number;impact:number};previous?:{likelihood:number;impact:number}}){
 const {t,copy}=useWords(),arrowId=useId().replaceAll(':','');return <div className="w-riskmap"><small>{t('Likelihood ↑','Kemungkinan ↑')}</small><div className="w-matrix-layout"><div className="w-y-axis">{[5,4,3,2,1].map(n=><span key={n}>{n}</span>)}</div><div className="w-matrix">{[5,4,3,2,1].flatMap(l=>[1,2,3,4,5].map(i=>{const matches=risks?.filter(r=>r.likelihood===l&&r.impact===i)||[],selected=value?.likelihood===l&&value?.impact===i;return <button type="button" key={l+'-'+i} disabled={!onChange} aria-label={t('Likelihood','Kemungkinan')+' '+l+', '+t('impact','dampak')+' '+i+', '+t('score','skor')+' '+l*i} className={(l*i>12?'high':l*i>6?'medium':'low')+(selected?' chosen':'')+(suggestion?.likelihood===l&&suggestion?.impact===i?' suggested':'')} onClick={()=>onChange?.({likelihood:l,impact:i})}>{suggestion?.likelihood===l&&suggestion?.impact===i?<span className="w-map-suggestion">S{selected&&<Check size={11}/>}</span>:selected?<Check size={17}/>:matches.length?<b title={matches.map(r=>copy(r.title)).join(', ')}>{matches.length}</b>:<small>{l*i}</small>}{previous?.likelihood===l&&previous?.impact===i&&<span className="w-map-previous" title={t('Previous score','Skor sebelumnya')}>P {l*i}</span>}</button>;}))}{previous&&suggestion&&(previous.likelihood!==suggestion.likelihood||previous.impact!==suggestion.impact)&&<svg className="w-map-move" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><defs><marker id={arrowId} viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z"/></marker></defs><path d={`M${(previous.impact-.5)*20} ${(5-previous.likelihood+.5)*20} L${(suggestion.impact-.5)*20} ${(5-suggestion.likelihood+.5)*20}`} markerEnd={`url(#${arrowId})`}/></svg>}{risks?.filter(r=>!Number.isInteger(r.likelihood)||!Number.isInteger(r.impact)).map(r=><span className="w-map-fraction" key={r.id} style={{left:((r.impact-.5)/5*100)+'%',top:((5-r.likelihood+.5)/5*100)+'%'}} title={copy(r.title)}>{r.likelihood*r.impact}</span>)}</div></div><div className="w-x-axis">{[1,2,3,4,5].map(n=><span key={n}>{n}</span>)}</div><small>{t('Impact →','Dampak →')}</small>{previous&&<div className="w-map-legend"><span><b>P</b> {t('Previous','Sebelumnya')} {previous.likelihood*previous.impact}</span><span><b>S</b> {t('Suggested','Usulan')} {suggestion?suggestion.likelihood*suggestion.impact:''}</span></div>}</div>;
}
