 return <><tr><td><button className="w-row-title" onClick={()=>setOpen(!open)} aria-expanded={open}>{copy(plan.title)}<ChevronDown size={16}/></button><small>{copy(risk?.title)}</small></td><td data-label={t('Owner','Penanggung jawab')}>{copy(plan.owner)}</td><td data-label={t('Due','Tenggat')}>{plan.dueDate}{plan.status==='Open'&&plan.dueDate<date&&<b className="w-danger">{t('Overdue','Lewat tenggat')}</b>}</td><td data-label={t('Status','Status')}>{plan.status==='Done'?t('Done','Selesai'):t('Open','Terbuka')}</td><td>L −{plan.likelihoodReduction} / I −{plan.impactReduction}</td></tr>{open&&<tr><td colSpan={5} className="w-expanded" ><p>{plan.notes}</p><label>{t('Implementation and effectiveness evidence','Bukti pelaksanaan dan efektivitas')}<textarea maxLength={1500} value={evidence} onChange={e=>setEvidence(e.target.value)}/></label><button className="w-quiet" onClick={()=>setEvidence(copy(risk?.evidenceHint))}><Shuffle size={14}/>{t('Fill evidence notes','Isi catatan bukti')}</button><button className="w-primary" disabled={busy||plan.status==='Open'&&!evidence.trim()} onClick={()=>action('/plans/'+plan.id,'PATCH',{status:plan.status==='Done'?'Open':'Done',evidence})}>{plan.status==='Done'?t('Reopen plan','Buka kembali rencana'):t('Mark done with evidence','Tandai selesai dengan bukti')}</button><p className="w-note">{t('Current risk remains unchanged. A risk owner must explicitly reassess the evidence.','Risiko saat ini tetap. Pemilik risiko harus menilai ulang bukti secara eksplisit.')}</p></td></tr>}</>;
